serverCard.body:
{
  "$schema": "https://static.modelcontextprotocol.io/schemas/v1/server-card.schema.json",
  "name": "com.example.gw/cookbook",
  "version": "1.0.0",
  "description": "Cookbook",
  "title": "Cookbook",
  "websiteUrl": "https://gw.example.com/llms.txt",
  "remotes": [
    {
      "type": "streamable-http",
      "url": "https://gw.example.com/mcp",
      "headers": [
        {
          "name": "Authorization",
          "description": "An API key issued per client by the owner.",
          "isRequired": true,
          "isSecret": true,
          "value": "Bearer {api_key}",
          "variables": {
            "api_key": {
              "description": "Your API key.",
              "isRequired": true,
              "isSecret": true
            }
          }
        }
      ],
      "supportedProtocolVersions": [
        "2026-07-28",
        "2025-11-25",
        "2025-06-18",
        "2025-03-26",
        "2024-11-05",
        "2024-10-07"
      ]
    }
  ]
}

